head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst71000";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $("#searchForm").find("input:checkbox[name=listTypeArr]").click(async function() {
                await scwin.fnCheckListType();
        });
        $("#searchForm").find("input:checkbox[name=invstgRsltArr]").click(async function() {
                await scwin.fnCheckInvstgRslt();
        });
        await scwin.fnInit();
        $(".ord-07").attr("onclick", "fnSetSearchDate5('2000-01-01', '1'); fnSwapSearchBtnDates('7'); return false;");
        $("#cal_fromDate").change(function() {
                chkPeriod2Mil($(this).val());
        });

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst71000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst71000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
// [저작] 기간 프리셋 버튼 — fnDisplaySearchBtnDates 재설계 (btn_cm 텍스트·gcc date 조합)

/**
 * @method
 * @name btn_pd_1w_onclick
 * @description 「1주」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_1w_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addDate(to, -7); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst71000.pd_1w' }); } };

/**
 * @method
 * @name btn_pd_1m_onclick
 * @description 「1개월」 클릭 이벤트
