 */
scwin.btn_pd_3m_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addMonth(to, -3); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst71000.pd_3m' }); } };

/**
 * @method
 * @name btn_pd_6m_onclick
 * @description 「6개월」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_6m_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addMonth(to, -6); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst71000.pd_6m' }); } };

/**
 * @method
 * @name btn_pd_1y_onclick
 * @description 「1년」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_1y_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addYear(to, -1); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst71000.pd_1y' }); } };

/**
 * @method
 * @name ipt_AKCKwd_onblur
 * @description 「회사명 찾기」 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_AKCKwd_onblur = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        chkValidChar(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst71000.ipt_AKCKwd_onblur' }); }
};

/**
 * @method
 * @name btn_fnFindCorpName_onclick
 * @description btn_fnFindCorpName 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnFindCorpName_onclick = function(e){
    try {
        fnFindCorpName(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst71000.btn_fnFindCorpName_onclick' }); }
};

/**
 * @method
 * @name cal_fromDate_onchange
 * @description 「청구일 기간 선택 첫번째」 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.cal_fromDate_onchange = function(e){
    try {
        scwin.fnChkLmtDate();return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst71000.cal_fromDate_onchange' }); }
};scwin.btn_fnSearchCorpName_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.fnSearchCorpName(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst71000.btn_fnSearchCorpName_onclick' }); }
};

/**
 * @method
 * @name btn_fnDownload_onclick
 * @description btn_fnDownload 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnDownload_onclick = async function(e){
    try {
        await scwin.fnDownload(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst71000.btn_fnDownload_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/listinvstg/listinvstgcom.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/listinvstg/listinvstgcom.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            if (fnAKCKwdSearchCodeType(($c.util.getComponent('ipt_AKCKwd')))) {
                await scwin.fnSearchCorpName();
            }
        }
    }
};

/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInit = async function () {
    scwin.fnCheckAllListType();
    scwin.fnCheckAllInvstgRslt();
    // 수동 전환 필요: fnDisplaySearchBtnDates(N) / fnDisplaySearchBtnDatesOnlyPeriod(N) → 작업본 dateSetting 관례로 재설계 (조회 기간 프리셋)
    //   KRX 방향: 재설계 축 — 작업본 정답지 관례 = scwin.dateSetting() + 기간 버튼 핸들러(btn_3mon_onclick 등)가 캘린더 setValue 로 기간을 직접 세움(ULDINF05800 계열 실증). 1:1 대체 함수가 없고 속성 승격도 아님 — 조회 영역 저작 관례로 실현. 요청 명부에서 제외(재설계 분류).
    //   근거: catalog/function-map (이 주석은 고쳐 쓴 뒤 지우십시오)
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDates( "4 ') */
    await scwin.fnSearchInit();
};

/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function () {
    await scwin.fnOrder("2", "D");
};

/**
 * @method
 * @name fnOrder
 * @description fn Order 처리
 * @param {*} mode mode
 * @param {*} stat stat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOrder = async function (mode, stat) {
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    if (!chkPeriod2Mil($c.util.getComponent('cal_fromDate').getValue())) {
        return;
    }
    if (!await scwin.fnCheckListType()) {
        return;
    }
    if (!await scwin.fnCheckInvstgRslt()) {
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_fromDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (($c.util.getComponent('cal_fromDate').getValue() === null ? '' : String($c.util.getComponent('cal_fromDate').getValue())) !== '' && ($c.util.getComponent('cal_toDate').getValue() === null ? '' : String($c.util.getComponent('cal_toDate').getValue())) !== '') {
        if (!($c.date.diffDate($c.util.getComponent('cal_fromDate').getValue(), $c.util.getComponent('cal_toDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('ipt_AKCKwd').getValue());
    if ($(document).find("select[id=ipt_currentPageSize]").val() !== null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchListInvstgCorpSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "listinvstgcom_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
    $("tr:even").addClass("active");
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnLegendTooltip( " ') */
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    if (!chkPeriod2Mil($c.util.getComponent('cal_fromDate').getValue())) {
        return;
    }
    if (!await scwin.fnCheckListType()) {
        return;
    }
    if (!await scwin.fnCheckInvstgRslt()) {
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_fromDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (($c.util.getComponent('cal_fromDate').getValue() === null ? '' : String($c.util.getComponent('cal_fromDate').getValue())) !== '' && ($c.util.getComponent('cal_toDate').getValue() === null ? '' : String($c.util.getComponent('cal_toDate').getValue())) !== '') {
        if (!($c.date.diffDate($c.util.getComponent('cal_fromDate').getValue(), $c.util.getComponent('cal_toDate').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('ipt_AKCKwd').getValue());
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchListInvstgCorpSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "listinvstgcom_down");
    await scwin.tx_fnDownload();
};

/**
 * @method
 * @name fnChkLmtDate
 * @description fn Chk Lmt Date 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnChkLmtDate = function () {
    chkPeriod2Mil($c.util.getComponent('cal_fromDate').getValue());
};

/**
 * @method
 * @name fnDetailView
 * @description fn Detail View 처리
 * @param {*} ipt_bizProcNo ipt_bizProcNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDetailView = async function (ipt_bizProcNo) {
    const wUrl = "/listinvstg/listinvstgcom.do?method=searchListInvstgCorpDetail&bizProcNo=" + ipt_bizProcNo;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { const __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(wUrl), { id: '예비심사기업상세보기', width: "865", height: "760" }, {});
};

/**
 * @method
 * @name fnCheckAllListType
 * @description fn Check All List Type 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckAllListType = function () {
    const chkLmnts = document.getElementsByName("listTypeArr");
    for (let i = 0; i < chkLmnts.length; i++) {
        chkLmnts[i].checked = true;
    }
};

/**
 * @method
 * @name fnCheckListType
 * @description fn Check List Type 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnCheckListType = async function () {
    const chkLmnts = document.getElementsByName("listTypeArr");
    let chkCnt = 0;
    let check_setting = "";
    for (let i = 0; i < chkLmnts.length; i++) {
        if (chkLmnts[i].checked === true) {
            check_setting += chkLmnts[i].value + "|";
            chkCnt++;
        }
    }
    if (chkCnt === 0) {
        await $c.win.alert('상장유형을 하나 이상 선택해주세요.');
        return false;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("listTypeArrStr", check_setting);
    return true;
};

/**
 * @method
 * @name fnCheckAllInvstgRslt
 * @description fn Check All Invstg Rslt 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckAllInvstgRslt = function () {
    const chkLmnts = document.getElementsByName("invstgRsltArr");
    for (let i = 0; i < chkLmnts.length; i++) {
        chkLmnts[i].checked = true;
    }
};

/**
 * @method
 * @name fnCheckInvstgRslt
 * @description fn Check Invstg Rslt 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnCheckInvstgRslt = async function () {
    const chkLmnts = document.getElementsByName("invstgRsltArr");
    let chkCnt = 0;
    let check_setting = "";
    for (let i = 0; i < chkLmnts.length; i++) {
        if (chkLmnts[i].checked === true) {
            check_setting += chkLmnts[i].value + "|";
            chkCnt++;
        }
    }
    if (chkCnt === 0) {
        await $c.win.alert('심사결과를 하나 이상 선택해주세요.');
        return false;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("invstgRsltArrStr", check_setting);
    return true;
};

/**
 * @method
 * @name fnSearch1
 * @description fn Search1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch1 = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearchCorpName
 * @description fn Search Corp Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpName = async function () {
    let val = $c.util.getComponent('ipt_AKCKwd').getValue(); if (val === null) { val = ''; }
    if (val !== "") {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('ipt_AKCKwd').getValue());
        fnAKCKwdSearchCorpNameAll();
    } else {
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", "");
        await scwin.fnSearchInit();
    }
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
};

/**
 * @method
 * @name fnSearchCorpNameAllCallBack
 * @description fn Search Corp Name All Call Back 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", '');
    if (items.length === 1) {
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", items[0].isurcd);
        await scwin.fnSearchCorpCode();
    } else {
        if (items.length > 1) {
            fnFindCorpName();
        } else {
            await scwin.fnSearchCorpCode();
        }
    }
};

/**
 * @method
 * @name fnSearchCorpCode
 * @description fn Search Corp Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpCode = async function () {
    await scwin.fnSearchInit();
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} ipt_isurCd ipt_isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} ipt_repIsuSrtCd ipt_repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} ipt_comAbbrv ipt_comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (ipt_isurCd, kisComCd, ipt_repIsuSrtCd, comNm, ipt_comAbbrv, isurSymbl, fssUnqNo) {
    let str = "";
    str += "isurCd : " + ipt_isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + ipt_repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + ipt_comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    if (ipt_repIsuSrtCd === "") {
        ipt_repIsuSrtCd = ipt_isurCd;
    }
    $c.util.getComponent('ipt_AKCKwd').setValue(ipt_comAbbrv);
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", ipt_isurCd);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", ipt_repIsuSrtCd);
};
